INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formatos nacionales', '[["Formato 1", "Finvoice 3.0"], ["Formato 2", "TEAPPSXML 3.0"], ["Alineación con la UE", "Ambos pueden generar una salida conforme con EN 16931"]]', 'Ninguno de los dos formatos garantiza automáticamente el cumplimiento de EN 16931 — la empresa o su proveedor de software debe verificar que la salida real cumple con el estándar.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'National formats';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Nationale Formate', '[["Format 1", "Finvoice 3.0"], ["Format 2", "TEAPPSXML 3.0"], ["EU-Ausrichtung", "Beide können EN-16931-konforme Ausgaben erzeugen"]]', 'Keines der beiden Formate garantiert automatisch die EN-16931-Konformität — das Unternehmen oder sein Softwareanbieter muss prüfen, dass die tatsächliche Ausgabe dem Standard entspricht.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'National formats';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Formats nationaux', '[["Format 1", "Finvoice 3.0"], ["Format 2", "TEAPPSXML 3.0"], ["Alignement UE", "Les deux peuvent produire une sortie conforme à l''EN 16931"]]', 'Aucun des deux formats ne garantit automatiquement la conformité à l''EN 16931 — l''entreprise ou son fournisseur de logiciel doit vérifier que la sortie réelle respecte bien la norme.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'National formats';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Facturas consolidadas', '[["Permitido bajo el estándar EN", "No"]]', 'Una factura consolidada tradicional que cobra varios pedidos en un único documento no encaja en la estructura a nivel de línea del estándar europeo — una limitación real si su proceso actual depende de la agrupación por lotes.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'Consolidated invoices';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Sammelrechnungen', '[["Zulässig nach EN-Standard", "Nein"]]', 'Eine herkömmliche Sammelrechnung, die mehrere Bestellungen in einem Dokument abrechnet, passt nicht zur zeilenbasierten Struktur des europäischen Standards — eine echte Einschränkung, wenn Ihr aktueller Prozess auf Sammelabrechnung beruht.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'Consolidated invoices';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Factures groupées', '[["Autorisé selon la norme EN", "Non"]]', 'Une facture groupée traditionnelle facturant plusieurs commandes dans un seul document ne s''inscrit pas dans la structure au niveau des lignes de la norme européenne — une contrainte réelle si votre processus actuel repose sur un regroupement par lots.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'Consolidated invoices';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Sin plataforma central', '[["Mecanismo de enrutamiento", "Directorio Verkkolaskuosoite"], ["Organizaciones registradas", "Más de 300.000"]]', 'A diferencia de los países con modelo de compensación que cuentan con una única plataforma gubernamental, Finlandia enruta las facturas a través del operador/portal que utilice cada contraparte — el directorio le indica cuál es.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'No central platform';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Keine zentrale Plattform', '[["Routing-Mechanismus", "Verkkolaskuosoite-Verzeichnis"], ["Gelistete Organisationen", "Über 300.000"]]', 'Anders als Clearing-Modell-Länder mit einer staatlichen Plattform leitet Finnland Rechnungen über den jeweils vom Geschäftspartner genutzten Betreiber/Portal weiter — das Verzeichnis zeigt Ihnen, welcher das ist.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'No central platform';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Aucune plateforme centrale', '[["Mécanisme de routage", "Annuaire Verkkolaskuosoite"], ["Organisations répertoriées", "Plus de 300 000"]]', 'Contrairement aux pays à modèle de contrôle disposant d''une plateforme gouvernementale unique, la Finlande achemine les factures via l''opérateur/portail utilisé par chaque interlocuteur — l''annuaire vous indique lequel.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'No central platform';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Soporte de verificación', '[["Lista de software preparado", "Mantenida por TIEKE ry"], ["Comprobación por parte del operador", "Algunos operadores verifican el cumplimiento antes de la transmisión"]]', 'Merece la pena confirmar si su operador concreto comprueba el cumplimiento de EN 16931 por usted, o si esa responsabilidad recae en su propio software.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'Verification support';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Unterstützung bei der Verifizierung', '[["Liste bereiter Software", "Geführt von TIEKE ry"], ["Prüfung durch den Betreiber", "Manche Betreiber prüfen die Konformität vor der Übermittlung"]]', 'Es lohnt sich zu klären, ob Ihr konkreter Betreiber die EN-16931-Konformität für Sie prüft oder ob diese Verantwortung bei Ihrer eigenen Software liegt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'Verification support';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Support de vérification', '[["Liste des logiciels prêts", "Tenue par TIEKE ry"], ["Contrôle côté opérateur", "Certains opérateurs vérifient la conformité avant transmission"]]', 'Il vaut la peine de vérifier si votre opérateur spécifique contrôle la conformité à l''EN 16931 pour vous, ou si cette responsabilité vous incombe via votre propre logiciel.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'file_format' AND dct.title = 'Verification support';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'B2G', '[["Estado", "Obligatorio"], ["Se aplica a", "Todos los niveles de gobierno"], ["Proveedores extranjeros", "Deben usar el formato EN 16931"]]', 'Este es el único requisito genuinamente vinculante en todo el régimen finlandés — todo lo demás descrito en esta página es voluntario o contractual.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2G';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2G', '[["Status", "Verpflichtend"], ["Gilt für", "Alle staatlichen Ebenen"], ["Ausländische Lieferanten", "Müssen das EN-16931-Format verwenden"]]', 'Dies ist die einzige wirklich verbindliche Anforderung im gesamten finnischen Regime — alles andere auf dieser Seite ist freiwillig oder vertraglich geregelt.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2G';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'B2G', '[["Statut", "Obligatoire"], ["S''applique à", "Tous les niveaux de gouvernement"], ["Fournisseurs étrangers", "Doivent utiliser le format EN 16931"]]', 'C''est la seule exigence véritablement contraignante de tout le régime finlandais — tout le reste décrit sur cette page est volontaire ou contractuel.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2G';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'B2B (nacional)', '[["Estado", "Voluntario — sin mandato"], ["Derecho a exigir", "Facturación superior a 10.000 €"], ["Compensación de la autoridad fiscal", "No requerida"]]', 'Una empresa puede exigir contractualmente facturas electrónicas a sus proveedores, y a menudo lo hace — pero no existe ningún requisito legal para emitirlas en absoluto.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2B (domestic)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2B (inländisch)', '[["Status", "Freiwillig — keine Vorgabe"], ["Anspruch", "Umsatz über 10.000 €"], ["Freigabe durch Steuerbehörde", "Nicht erforderlich"]]', 'Ein Unternehmen kann vertraglich auf E-Rechnungen von Lieferanten bestehen, und tut dies auch häufig — es besteht jedoch überhaupt keine gesetzliche Pflicht, diese auszustellen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2B (domestic)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'B2B (national)', '[["Statut", "Volontaire — aucune obligation"], ["Droit d''exiger", "Chiffre d''affaires supérieur à 10 000 €"], ["Contrôle de l''administration fiscale", "Non requis"]]', 'Une entreprise peut exiger contractuellement des factures électroniques de ses fournisseurs, et le fait souvent — mais il n''existe aucune obligation légale de les émettre.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2B (domestic)';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'B2C', '[["Estado", "Sin mandato"]]', 'Los consumidores pueden recibir facturas electrónicas a través de la banca en línea, Suomi.fi Messages o el servicio OmaPosti de Posti, pero nada obliga a una empresa a ofrecerlo.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2C';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2C', '[["Status", "Keine Vorgabe"]]', 'Verbraucher können E-Rechnungen über Online-Banking, Suomi.fi-Nachrichten oder den OmaPosti-Dienst von Posti empfangen, doch nichts verpflichtet ein Unternehmen, dies anzubieten.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2C';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'B2C', '[["Statut", "Aucune obligation"]]', 'Les consommateurs peuvent recevoir des factures électroniques via la banque en ligne, Suomi.fi Messages, ou le service OmaPosti de Posti, mais rien n''oblige une entreprise à le proposer.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'B2C';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'B2B intracomunitario', '[["Estado actual", "Aún no sujeto a ningún mandato finlandés"], ["Pasa a ser obligatorio", "1 de julio de 2030, en toda la UE (ViDA)"]]', 'Finlandia planea implementarlo justo en el plazo de la UE, en lugar de adelantarse como han optado por hacer varios otros países de este seguimiento.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'Intra-EU B2B';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Innergemeinschaftliches B2B', '[["Aktueller Status", "Noch keiner finnischen Vorgabe unterworfen"], ["Wird verpflichtend", "1. Juli 2030, EU-weit (ViDA)"]]', 'Finnland plant die Umsetzung erst zur EU-Frist selbst, statt ihr voraus zu sein, wie es mehrere andere Länder in diesem Tracker gewählt haben.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'Intra-EU B2B';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'B2B intracommunautaire', '[["Statut actuel", "Pas encore soumis à une obligation finlandaise"], ["Devient obligatoire", "1er juillet 2030, à l''échelle de l''UE (ViDA)"]]', 'La Finlande prévoit de mettre en œuvre l''obligation à l''échéance même de l''UE, plutôt que de la devancer comme l''ont choisi de faire plusieurs autres pays de ce suivi.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'scope_transmission' AND dct.title = 'Intra-EU B2B';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'No existe un régimen de sanciones B2B', NULL, NULL, 'Dado que la facturación electrónica B2B nacional no es obligatoria, realmente no hay ninguna multa o sanción que describir aquí — una diferencia real con respecto a todos los países con modelo de compensación o CTC de este seguimiento.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'No B2B penalty framework exists';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Es existiert kein B2B-Sanktionsrahmen', NULL, NULL, 'Da die inländische B2B-E-Rechnungsstellung nicht verpflichtend ist, gibt es hier tatsächlich kein Bußgeld oder keine Sanktion zu beschreiben — ein echter Unterschied zu jedem Clearing- oder CTC-Modell-Land in diesem Tracker.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'No B2B penalty framework exists';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Aucun cadre de sanctions B2B n''existe', NULL, NULL, 'Étant donné que la facturation électronique B2B nationale n''est pas obligatoire, il n''y a véritablement aucune amende ou sanction à décrire ici — une différence réelle par rapport à tous les pays à modèle de contrôle ou CTC de ce suivi.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'No B2B penalty framework exists';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'El verdadero riesgo es comercial, no legal', NULL, NULL, 'Una empresa que no pueda enviar facturas electrónicas corre el riesgo de perder frente a sus competidores contratos con contrapartes que lo exijan — especialmente las grandes empresas que ejercen su derecho legal en virtud de la Ley de 2019.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'The real risk is commercial, not legal';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Das eigentliche Risiko ist kommerzieller, nicht rechtlicher Art', NULL, NULL, 'Ein Unternehmen, das keine E-Rechnungen versenden kann, riskiert, gegenüber Wettbewerbern Aufträge bei Geschäftspartnern zu verlieren, die dies verlangen — insbesondere bei größeren Unternehmen, die ihren gesetzlichen Anspruch aus dem Gesetz von 2019 geltend machen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'The real risk is commercial, not legal';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Le véritable risque est commercial, pas juridique', NULL, NULL, 'Une entreprise incapable d''envoyer des factures électroniques risque de perdre des contrats face à des concurrents auprès d''interlocuteurs qui l''exigent — en particulier les grandes entreprises exerçant leur droit légal au titre de la loi de 2019.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'The real risk is commercial, not legal';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'El incumplimiento en B2G es la única excepción real', NULL, NULL, 'No enviar facturas electrónicas a un organismo gubernamental finlandés no es una cuestión de elección — este es el único ámbito en el que el régimen finlandés funciona realmente como un mandato.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'B2G non-compliance is the one real exception';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'B2G-Nichteinhaltung ist die einzige echte Ausnahme', NULL, NULL, 'Keine E-Rechnungen an eine finnische Regierungsstelle zu senden, ist keine Frage der Wahl — dies ist der einzige Bereich, in dem Finnlands Regime tatsächlich wie eine Vorgabe funktioniert.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'B2G non-compliance is the one real exception';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Le non-respect du B2G est la seule véritable exception', NULL, NULL, 'Ne pas envoyer de factures électroniques à un organisme gouvernemental finlandais n''est pas une question de choix — c''est le seul domaine où le régime finlandais fonctionne véritablement comme une obligation.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'B2G non-compliance is the one real exception';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Vigile de cerca la ventana de preparación de 2028', NULL, NULL, 'Dado que no se ha fijado ninguna fecha B2B nacional, los propios preparativos de 2028 señalados por el gobierno son el indicador temprano más concreto de lo que podría llegar antes del plazo de la UE de 2030.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'Watch the 2028 preparation window closely';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Behalten Sie das Vorbereitungsfenster 2028 genau im Auge', NULL, NULL, 'Da kein inländisches B2B-Datum feststeht, sind die von der Regierung selbst signalisierten Vorbereitungen für 2028 der konkreteste frühe Hinweis darauf, was vor der EU-Frist 2030 kommen könnte.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'Watch the 2028 preparation window closely';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Surveillez de près la fenêtre de préparation 2028', NULL, NULL, 'Comme aucune date B2B nationale n''est fixée, les préparatifs de 2028 signalés par le gouvernement lui-même constituent l''indicateur précoce le plus concret de ce qui pourrait survenir avant l''échéance de l''UE en 2030.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id JOIN deep_dive_card_translations dct ON dct.card_id = dc.id AND dct.lang = 'en' WHERE c.name_en = 'Finland' AND dc.section = 'penalties_related' AND dct.title = 'Watch the 2028 preparation window closely';

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si suministra a algún organismo del sector público finlandés, confirme ahora su capacidad de facturación electrónica', 'Esto ha sido la norma desde 2020 — no es un requisito nuevo, y los compradores públicos lo esperarán como algo básico.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'If you supply any Finnish public-sector body, confirm e-invoicing capability now';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie eine finnische öffentliche Stelle beliefern, bestätigen Sie jetzt Ihre E-Invoicing-Fähigkeit', 'Dies ist seit 2020 die Norm — keine neue Anforderung, und öffentliche Auftraggeber werden dies als Grundvoraussetzung erwarten.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'If you supply any Finnish public-sector body, confirm e-invoicing capability now';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous fournissez un organisme public finlandais, confirmez dès maintenant votre capacité de facturation électronique', 'C''est la norme depuis 2020 — ce n''est pas une nouvelle exigence, et les acheteurs publics l''attendront comme un minimum de base.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'If you supply any Finnish public-sector body, confirm e-invoicing capability now';
