INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie, ob Ihre Finvoice-3.0- oder TEAPPSXML-3.0-Ausgabe tatsächlich EN-16931-konform ist', 'Prüfen Sie die Bereitschaftsliste von TIEKE ry für Ihre Software, oder bestätigen Sie, dass Ihr Betreiber die Konformität vor der Übermittlung prüft.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Verify your Finvoice 3.0 or TEAPPSXML 3.0 output is genuinely EN 16931-compliant';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Vérifiez que votre sortie Finvoice 3.0 ou TEAPPSXML 3.0 est réellement conforme à l''EN 16931', 'Consultez la liste de préparation de TIEKE ry pour votre logiciel, ou vérifiez que votre opérateur contrôle la conformité avant transmission.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Verify your Finvoice 3.0 or TEAPPSXML 3.0 output is genuinely EN 16931-compliant';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Utilice el directorio Verkkolaskuosoite para encontrar el enrutamiento correcto para cada contraparte', 'No existe una única plataforma — este directorio le indica qué operador o portal llega realmente a una organización determinada.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Use the Verkkolaskuosoite directory to find the right routing for each counterparty';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Nutzen Sie das Verkkolaskuosoite-Verzeichnis, um das richtige Routing für jeden Geschäftspartner zu finden', 'Es gibt keine einzige Plattform — dieses Verzeichnis zeigt Ihnen, welcher Betreiber oder welches Portal eine bestimmte Organisation tatsächlich erreicht.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Use the Verkkolaskuosoite directory to find the right routing for each counterparty';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Utilisez l''annuaire Verkkolaskuosoite pour trouver le bon routage pour chaque interlocuteur', 'Il n''existe pas de plateforme unique — cet annuaire vous indique quel opérateur ou portail atteint réellement une organisation donnée.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Use the Verkkolaskuosoite directory to find the right routing for each counterparty';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Para el B2B nacional, compruebe los requisitos contractuales específicos de sus clientes', 'No asuma que existe un mandato legal solo porque la facturación electrónica esté muy extendida — confirme lo que realmente exigen las contrapartes con las que trata.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'For domestic B2B, check your specific customers'' contractual requirements';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Prüfen Sie bei inländischem B2B die spezifischen vertraglichen Anforderungen Ihrer Kunden', 'Gehen Sie nicht davon aus, dass eine gesetzliche Vorgabe besteht, nur weil E-Invoicing weit verbreitet ist — klären Sie, was von den Geschäftspartnern, mit denen Sie zu tun haben, tatsächlich verlangt wird.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'For domestic B2B, check your specific customers'' contractual requirements';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Pour le B2B national, vérifiez les exigences contractuelles propres à vos clients', 'Ne présumez pas qu''une obligation légale existe simplement parce que la facturation électronique est répandue — vérifiez ce qui est réellement exigé par les interlocuteurs avec lesquels vous traitez.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'For domestic B2B, check your specific customers'' contractual requirements';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Vuelva a consultar esta página periódicamente de cara a 2028', 'El gobierno finlandés ha señalado que los preparativos del ViDA comenzarán en torno a 2028 — un calendario nacional más firme podría surgir bastante antes del propio plazo de la UE de 2030.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Revisit this page periodically ahead of 2028';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Besuchen Sie diese Seite im Vorfeld von 2028 regelmäßig erneut', 'Die finnische Regierung hat signalisiert, dass die ViDA-Vorbereitungen um 2028 beginnen werden — ein konkreterer inländischer Zeitplan könnte schon deutlich vor der eigentlichen EU-Frist 2030 entstehen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Revisit this page periodically ahead of 2028';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Consultez à nouveau cette page périodiquement à l''approche de 2028', 'Le gouvernement finlandais a indiqué que les préparatifs ViDA débuteraient autour de 2028 — un calendrier national plus ferme pourrait émerger bien avant l''échéance de l''UE elle-même en 2030.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id JOIN deep_dive_step_translations dst ON dst.step_id = ds.id AND dst.lang = 'en' WHERE c.name_en = 'Finland' AND dst.title = 'Revisit this page periodically ahead of 2028';

